    {
      "id": "s1",
      "title": "Collect M3 Ultra & MLX specs",
      "kind": "research",
      "instructions": "Gather the relevant hardware specifications for the Apple M3 Ultra (GPU memory, unified memory, compute throughput) and the capabilities/limitations of the MLX framework (GPU memory handling, supported precision, typical batch sizes). Provide the data in a short bullet list.",
      "depends_on": []
    },
    {
      "id": "s2",
      "title": "Estimate memory footprint",
      "kind": "research",
      "instructions": "Using the specs from s1, calculate the approximate GPU/unified memory needed for:\n- Full fine‑tuning of a 4 B model (weights, optimizer states, activations).\n- LoRA fine‑tuning (base model + LoRA adapters, no optimizer for full weights).\nPresent the results in a table (method vs memory usage in GB).",
      "depends_on": ["s1"]
    },
    {
      "id": "s3",
      "title": "Estimate training time for 5k examples",
      "kind": "research",
      "instructions": "Based on typical throughput numbers for the M3 Ultra with MLX (tokens/sec per GPU) and the batch sizes implied by the memory estimates, compute a rough wall‑clock time to train 5 000 examples for both full fine‑tuning and LoRA. Show assumptions and provide the times in minutes/hours.",
      "depends_on": ["s1", "s2"]
    },
    {
      "id": "s4",
      "title": "Summarize quality trade‑offs",
      "kind": "research",
      "instructions": "Provide a concise summary (3‑5 bullet points) of known quality differences between LoRA and full fine‑tuning for ~4 B models, citing recent papers or benchmarks (e.g., performance on downstream tasks, over‑fitting risk, flexibility).",
      "depends_on": []
    },
    {
      "id": "s5",
      "title": "Draft one‑page recommendation",
      "kind": "writing",
      "instructions": "Combine the outputs of s2, s3, and s4 into a single‑page recommendation (≈300‑400 words). Include:\n- Memory needed for each method.\n- Rough training time for 5 000 examples.\n- Quality trade‑offs.\n- A clear recommendation on which approach to start with and why.\nFormat the document as plain text with headings for each section.",
      "depends_on": ["s2", "s3", "s4"]
    }
  ]
}

